customElements.define('calendar-viewer',class extends HTMLElement{constructor(){super();this.CALENDAR_TOOLBAR='[data-calendar-toolbar]';this.CALENDAR_VIEW='[data-calendar-view]';this.CALENDAR_INFO_PANEL='[data-calendar-info]';this.INFO_TITLE='[data-calendar-title]';this.INFO_SUBTITLE='[data-calendar-subtitle]';this.INFO_TAB_CONTROLS='[data-tab-controls]';this.INFO_TABS='[data-calendar-tab]';this.INFO_TAB_PANELS='[data-tab-panel]';this.INFO_TAG_TEMPLATE='[data-tag-template]';this.NEXT_MONTH_BTN='[data-next-month]';this.PREV_MONTH_BTN='[data-prev-month]';this.MONTHS=["#JAN","#FEB","#MAR","#APR","#MAY","#JUN","#JUL","#AUG","#SEP","#OCT","#NOV","#DEC"];this.monthData=[];this.lastActiveHighlight;this.currentMonthIndex=0}
connectedCallback(){this.setupComponent()}
setupComponent(){this.calendarDataPath=this.getAttribute('calendar-data');this.getDataFromJSON(this.calendarDataPath,(data)=>{this.monthData=data});this.calendarViewElement=document.querySelector(this.CALENDAR_VIEW);this.monthHighlights=Array.from(this.querySelectorAll(this.MONTHS.join(",")));this.nextMonthBtnElement=this.querySelector(this.NEXT_MONTH_BTN);this.prevMonthBtnElement=this.querySelector(this.PREV_MONTH_BTN);this.infoTabControls=this.querySelector(this.INFO_TAB_CONTROLS);if(this.infoTabControls){this.infoTabControls.classList.add('hide')}
this.infoTabElements=Array.from(this.querySelectorAll(this.INFO_TABS));this.infoTitleElement=this.querySelector(this.INFO_TITLE);this.infoSubTitleElement=this.querySelector(this.INFO_SUBTITLE);this.infoPanelElements=Array.from(this.querySelectorAll(this.INFO_TAB_PANELS));this.infoTagTemplate=this.querySelector(this.INFO_TAG_TEMPLATE);this.setupListeners()}
setupListeners(){if(this.monthHighlights.length>0){this.monthHighlights.forEach(highlight=>{highlight.addEventListener('click',()=>{this.setActiveMonthHighlight(highlight);this.matchDataToHighlight(highlight)})});this.monthHighlights.forEach(highlight=>{highlight.addEventListener('keydown',(event)=>{if(event.key==='Enter'||event.key===' '){this.setActiveMonthHighlight(highlight);this.matchDataToHighlight(highlight)}})})}
if(this.nextMonthBtnElement){this.nextMonthBtnElement.addEventListener('click',()=>{this.goToNextMonth()})}
if(this.prevMonthBtnElement){this.prevMonthBtnElement.addEventListener('click',()=>{this.goToPreviousMonth()})}}
matchDataToHighlight(highlight){this.monthData.filter(data=>{const shortName=data.short.toLocaleLowerCase().trim();const idName=highlight.id.toLocaleLowerCase().trim();if(shortName===idName){this.currentMonthIndex=data.id;this.updateInfoPanel(data)}})}
setActiveMonthHighlight(highlight){if(this.lastActiveHighlight)
this.lastActiveHighlight.classList.remove("active");highlight.classList.add("active");this.lastActiveHighlight=highlight}
goToNextMonth(){this.currentMonthIndex++;if(this.currentMonthIndex>12){this.currentMonthIndex=1}
const toMonth=this.monthData.find(month=>{return month.id===this.currentMonthIndex});const monthShortName=toMonth.short.toUpperCase().trim();const toHighlight=this.getHighlightFromShortName(monthShortName);this.setActiveMonthHighlight(toHighlight);this.updateInfoPanel(toMonth)}
goToPreviousMonth(){this.currentMonthIndex--;if(this.currentMonthIndex<1){this.currentMonthIndex=12}
const toMonth=this.monthData.find(month=>{return month.id===this.currentMonthIndex});const monthShortName=toMonth.short.toUpperCase().trim();const toHighlight=this.getHighlightFromShortName(monthShortName);this.setActiveMonthHighlight(toHighlight);this.updateInfoPanel(toMonth)}
updateInfoPanel(monthObject){if(monthObject===null||typeof monthObject!=='object'||Array.isArray(monthObject))
return;this.updateTabs(monthObject);if(this.infoTitleElement&&monthObject.name!==undefined)
this.infoTitleElement.textContent=monthObject.name;if(this.infoSubTitleElement&&monthObject.season!==undefined)
this.infoSubTitleElement.textContent=monthObject.season}
updateTabs(monthObject){if(monthObject===null||typeof monthObject!=='object'||Array.isArray(monthObject))
return;if(this.infoTabControls){this.infoTabControls.classList.remove('hide')}
if(Object.hasOwn(monthObject,'resources')&&this.infoTabElements){Object.entries(monthObject.resources).forEach(([key,value])=>{this.infoTabElements.forEach(tab=>{const keyName=key.toLowerCase().trim();const tabName=tab.name.toLowerCase().trim();if(tabName===keyName){if(value.size===0){tab.disabled=!0}else{this.updateTabPanels(key,value)}}})})}}
updateTabPanels(panelName,resourceArray){if(!Array.isArray(resourceArray))
return;this.infoPanelElements.forEach(panel=>{if(panel.dataset.tabName===panelName){const docFrag=new DocumentFragment();const uList=document.createElement('ul');uList.classList.add("list-unstyled","d-flex","flex-wrap","gap-2","mt-3");resourceArray.forEach(resource=>{const infoTag=this.infoTagTemplate.content.cloneNode(!0);const lItem=infoTag.querySelector('li');const tagTitle=infoTag.querySelector('.tag-title');const progressElement=infoTag.querySelector('.progress');const progressBar=infoTag.querySelector('.progress-bar');const fillColorClass=`bg-${panel.dataset.tabName.toLowerCase().trim().replace('_', '-')}`;let fillDirection="ltr";let percentWidth="100";if(resource.fill_class&&resource.fill_class.includes("-")){const[direction,width]=resource.fill_class.split("-");const fillWidth=parseInt(width,10);fillDirection=(direction==='start')?'ltr':'rtl';percentWidth=`${fillWidth}`}else if(resource.fill_class==='none'||!resource.fill_class){percentWidth='0'}
if(Object.hasOwn(resource,'tooltip_text')){this.setupInfoTagTooltip(tagTitle,lItem,resource)}else{tagTitle.textContent=resource.name}
if(progressElement&&progressBar){progressBar.classList.add(fillColorClass);progressElement.setAttribute('dir',fillDirection);progressElement.setAttribute('aria-valuenow',percentWidth);progressBar.style.width=`${percentWidth}%`}
uList.appendChild(infoTag)});docFrag.appendChild(uList);panel.replaceChildren(docFrag)}})}
setupInfoTagTooltip(tagTitleElement,infoTagElement,resource){infoTagElement.classList.add("position-relative");infoTagElement.setAttribute("data-bs-toggle","tooltip");infoTagElement.setAttribute("data-bs-title",resource.tooltip_text);infoTagElement.setAttribute('aria-description',resource.tooltip_text);const badge=document.createElement('span');badge.classList.add("position-absolute","top-0","start-100","translate-middle","badge","rounded-circle","bg-dark");badge.textContent='i';tagTitleElement.textContent=resource.name;infoTagElement.append(badge);if(typeof bootstrap!=='undefined')
new bootstrap.Tooltip(infoTagElement);}
getHighlightFromShortName(shortName){if(this.monthHighlights.length===0)
return null;const toHighlight=this.monthHighlights.find(highlight=>{const highlightShortName=highlight.id.toUpperCase().trim();if(highlightShortName===shortName)
return highlight});return toHighlight}
getDataFromJSON(path,callback){let request=new XMLHttpRequest();request.open('GET',path,!0);request.onload=function(){if(this.status>=200&&this.status<400){try{let data=JSON.parse(this.response);callback(data)}catch(error){console.error(`Error parsing JSON from ${path}`,error);callback(null)}}else{console.warn(`The resource at ${path} returned an error: ${this.status}`);callback(null)}};request.onerror=function(){console.warn(`The resource at ${path} could not be loaded (network error).`);callback(null)};request.send()}})